select is((select count(*)from public.sales_tracking_attachments where report_id=(select id from public.sales_tracking_reports where branch_id='3e000000-0000-4000-8000-000000000001'and version_number=2)and deleted_at is null),0::bigint,'Empty re-entry has no replacement photos');
select is((select count(*)from public.sales_tracking_attachments where report_id=(select id from public.sales_tracking_reports where branch_id='3e000000-0000-4000-8000-000000000001'and version_number=1)and deleted_at is null),1::bigint,'Source photo remains scoped to v1');
