select throws_ok(format($$select public.save_sales_tracking_draft('1e000000-0000-4000-8000-000000000001','3e000000-0000-4000-8000-000000000001','%s',1,'closing_shift','[{"entry_date":"%s","actual_cash":"1","actual_credit":"0","pos_cash":"1","pos_credit":"0","online_delivery":"0"}]','[{"entry_date":"%s","remaining_cash":"1","denom_1":1}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'PT409','sales tracking correction is open','Normal save cannot mutate an open correction');
